            Node("return_difference", "return_difference", "return difference", "For the specified parameters, the following hypotheses imply the stated relation: (low : Bool) (a : Return) (x y : ℝ) : run low a x-run low a y=rho^a.val.1*chi^a.val.2*(x-y)", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
