            Node("return_slope", "return_slope", "return slope", "For the specified parameters, the following hypotheses imply the stated relation: (a : Return) : rho^a.val.1*chi^a.val.2=g^(actualWeight a)", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("totalWeight", "totalWeight", "totalWeight", "The mathematical data are specified by totalWeight(as : List Return) := (as.map actualWeight).sum.", DescribeRole.Definition, AssessedProvenance.FromRepo()),
            Node("fullBudget_order", "fullBudget_order", "fullBudget order", "For the specified parameters, the following hypotheses imply the stated relation: (anchor : Bool) (exec : List Return) : fullBudget true anchor exec ≤ fullBudget false anchor exec", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("run_floor", "run_floor", "run floor", "For the specified parameters, the following hypotheses imply the stated relation: (low : Bool) (a : Return) (D : ℝ) (hD : 0 ≤ D) (hh : D ≤ h low) : A low ≤ run low a D", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("initial_floor", "initial_floor", "initial floor", "For the specified parameters, the following hypotheses imply the stated relation: (low anchor : Bool) : A low ≤ initial low anchor", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("execute_floor", "execute_floor", "execute floor", "For the specified parameters, the following hypotheses imply the stated relation: (low : Bool) (as : List Return) (D : ℝ) (hD : A low ≤ D) (hh : D ≤ h low) : A low ≤ execute low as D", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("A_nonneg", "A_nonneg", "A nonneg", "For the specified parameters, the following hypotheses imply the stated relation: 0 ≤ A false", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("auto_nonneg", "auto_nonneg", "auto nonneg", "For the specified parameters, the following hypotheses imply the stated relation: (K : ℕ) : 0 ≤ Statement.autoCost K", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
            Node("fullBudget_guard", "fullBudget_guard", "fullBudget guard", "For the specified parameters, the following hypotheses imply the stated relation: (anchor : Bool) (K : ℕ) (d gain b : ℝ) (as : List Return) (hK : 2 ≤ K) (hb : b=lambda-g^2*chi^K*d) (hw : Statement.weak K (d+gain) as (initial false anchor)) : ∀ low, fullBudget low anchor as ≤ max (Statement.autoCost K) (b-g^2*chi^K*gain)", DescribeRole.Theorem, AssessedProvenance.FromRepo()),
